import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 오류 처리 방식은 오류 건 제외 후 정상 건 반영(EXCLUDE_ERROR)으로 고정한다.
const PROCESS_MODE = 'EXCLUDE_ERROR';
// 가정: 업로드 파일은 탭으로 구분한 텍스트이고 첫 줄은 아래 머리글과 같아야 한다.
// 가정: 요청에 파일 이름이 없어 '업로드대상.tsv' 형태로 저장한다.
const LAYOUTS: Record<string, string[]> = {
  PARTNER: ['projectId', 'code', 'partnerType', 'name', 'shortName', 'businessRegNo', 'tradeStartDate', 'tradeEndDate'],
  CARRYOVER: ['fiscalYear', 'accountSubjectId', 'partnerId', 'projectId', 'carryoverAmount'],
  ANNUAL_LEAVE: ['employeeId', 'baseYear', 'grantedDays'],
};
const TARGETS = ['PARTNER', 'PERSONNEL_RECORD', 'ANNUAL_LEAVE', 'PAYROLL', 'ASSET', 'ATTENDANCE', 'CARRYOVER', 'COMMUTE_RECORD', 'EDUCATION_ATTENDEE', 'DAILY_WORKER_PAYMENT'];

type Db = {
  query: (sql: string, params?: Record<string, unknown>) => Promise<any[]>;
  execute: (sql: string, params?: Record<string, unknown>) => Promise<number>;
};
type Cells = Record<string, string>;

const isInt = (s: string) => /^-?\d+$/.test(s);
const isNum = (s: string) => /^-?\d+(\.\d+)?$/.test(s);
const isDate = (s: string) => /^\d{4}-\d{2}-\d{2}$/.test(s);
const orNull = (s: string) => (s === '' ? null : s);

async function recordChange(db: Db, userId: string, targetType: string, targetId: unknown, content: string) {
  await db.execute(
    `INSERT INTO change_history (changer_id, target_type, target_id, change_type, changed_at, change_content, created_at, updated_at)
     VALUES (CAST(:userId AS bigint), :targetType, CAST(:targetId AS bigint), '엑셀 업로드', now(), :content, now(), now())`,
    { userId, targetType, targetId: String(targetId), content },
  );
}

async function exists(db: Db, table: string, column: string, id: string): Promise<boolean> {
  const rows = await db.query(`SELECT 1 AS "found" FROM ${table} WHERE ${column} = CAST(:id AS bigint)`, { id });
  return rows.length > 0;
}

async function savePartner(db: Db, userId: string, v: Cells): Promise<string | null> {
  if (!isInt(v.projectId) || v.code === '' || v.name === '') return '필수값(프로젝트, 거래처 코드, 거래처 명칭)이 없거나 형식이 올바르지 않습니다.';
  if (v.partnerType !== '일반' && v.partnerType !== '금융') return '거래처 유형은 일반 또는 금융이어야 합니다.';
  if (v.code.length > 20 || v.name.length > 200) return '거래처 코드 또는 명칭이 너무 깁니다.';
  if (v.businessRegNo !== '' && !/^\d{10}$/.test(v.businessRegNo)) return '사업자등록번호는 하이픈 없이 10자리 숫자여야 합니다.';
  if (v.tradeStartDate !== '' && !isDate(v.tradeStartDate)) return '거래 시작일 형식이 올바르지 않습니다.';
  if (v.tradeEndDate !== '' && !isDate(v.tradeEndDate)) return '거래 종료일 형식이 올바르지 않습니다.';
  if (v.tradeStartDate !== '' && v.tradeEndDate !== '' && v.tradeEndDate < v.tradeStartDate) return '거래 종료일은 거래 시작일보다 빠를 수 없습니다.';
  if (!(await exists(db, 'project', 'project_id', v.projectId))) return '존재하지 않는 프로젝트입니다.';
  const params = {
    projectId: v.projectId,
    code: v.code,
    partnerType: v.partnerType,
    name: v.name,
    shortName: orNull(v.shortName),
    businessRegNo: orNull(v.businessRegNo),
    tradeStartDate: orNull(v.tradeStartDate),
    tradeEndDate: orNull(v.tradeEndDate),
  };
  const found = await db.query('SELECT partner_id AS "partnerId" FROM partner WHERE code = :code', { code: v.code });
  if (found.length > 0) {
    const id = found[0].partnerId;
    await db.execute(
      `UPDATE partner SET project_id = CAST(:projectId AS bigint), partner_type = :partnerType, name = :name, short_name = :shortName,
         business_reg_no = :businessRegNo, trade_start_date = CAST(:tradeStartDate AS date), trade_end_date = CAST(:tradeEndDate AS date), updated_at = now()
       WHERE partner_id = CAST(:id AS bigint)`,
      { ...params, id: String(id) },
    );
    await recordChange(db, userId, 'partner', id, '거래처 수정: ' + v.code);
    return null;
  }
  const rows = await db.query(
    `INSERT INTO partner (project_id, code, partner_type, name, short_name, business_reg_no, trade_start_date, trade_end_date, created_at, updated_at)
     VALUES (CAST(:projectId AS bigint), :code, :partnerType, :name, :shortName, :businessRegNo, CAST(:tradeStartDate AS date), CAST(:tradeEndDate AS date), now(), now())
     RETURNING partner_id AS "partnerId"`,
    params,
  );
  await recordChange(db, userId, 'partner', rows[0].partnerId, '거래처 등록: ' + v.code);
  return null;
}

async function saveCarryover(db: Db, userId: string, v: Cells): Promise<string | null> {
  if (!isInt(v.fiscalYear) || !isInt(v.accountSubjectId) || v.carryoverAmount === '') return '필수값(회계연도, 계정과목, 이월 금액)이 없거나 형식이 올바르지 않습니다.';
  if (!isNum(v.carryoverAmount)) return '이월 금액은 숫자여야 합니다.';
  if (v.partnerId !== '' && !isInt(v.partnerId)) return '거래처 형식이 올바르지 않습니다.';
  if (v.projectId !== '' && !isInt(v.projectId)) return '프로젝트 형식이 올바르지 않습니다.';
  if (!(await exists(db, 'account_subject', 'account_subject_id', v.accountSubjectId))) return '존재하지 않는 계정과목입니다.';
  if (v.partnerId !== '' && !(await exists(db, 'partner', 'partner_id', v.partnerId))) return '존재하지 않는 거래처입니다.';
  if (v.projectId !== '' && !(await exists(db, 'project', 'project_id', v.projectId))) return '존재하지 않는 프로젝트입니다.';
  const params = {
    fiscalYear: v.fiscalYear,
    accountSubjectId: v.accountSubjectId,
    partnerId: orNull(v.partnerId),
    projectId: orNull(v.projectId),
    carryoverAmount: v.carryoverAmount,
  };
  const found = await db.query(
    `SELECT account_carryover_id AS "accountCarryoverId", closing_status AS "closingStatus" FROM account_carryover
     WHERE fiscal_year = CAST(:fiscalYear AS integer) AND account_subject_id = CAST(:accountSubjectId AS bigint)
       AND partner_id IS NOT DISTINCT FROM CAST(:partnerId AS bigint) AND project_id IS NOT DISTINCT FROM CAST(:projectId AS bigint)`,
    params,
  );
  if (found.length > 0) {
    if (found[0].closingStatus === '마감') return '마감된 이월내역입니다. 마감 취소 후 변경해야 합니다. (PERIOD_CLOSED_OR_APPROVED)';
    const id = found[0].accountCarryoverId;
    await db.execute(
      'UPDATE account_carryover SET carryover_amount = CAST(:carryoverAmount AS numeric), updated_at = now() WHERE account_carryover_id = CAST(:id AS bigint)',
      { carryoverAmount: v.carryoverAmount, id: String(id) },
    );
    await recordChange(db, userId, 'account_carryover', id, '이월내역 금액 수정');
    return null;
  }
  const rows = await db.query(
    `INSERT INTO account_carryover (fiscal_year, account_subject_id, partner_id, project_id, carryover_amount, closing_status, created_at, updated_at)
     VALUES (CAST(:fiscalYear AS integer), CAST(:accountSubjectId AS bigint), CAST(:partnerId AS bigint), CAST(:projectId AS bigint), CAST(:carryoverAmount AS numeric), '미마감', now(), now())
     RETURNING account_carryover_id AS "accountCarryoverId"`,
    params,
  );
  await recordChange(db, userId, 'account_carryover', rows[0].accountCarryoverId, '이월내역 등록');
  return null;
}

async function saveAnnualLeave(db: Db, userId: string, v: Cells): Promise<string | null> {
  if (!isInt(v.employeeId) || !isInt(v.baseYear) || v.grantedDays === '') return '필수값(임직원, 기준연도, 생성일수)이 없거나 형식이 올바르지 않습니다.';
  if (!isNum(v.grantedDays) || Number(v.grantedDays) < 0) return '생성일수는 0 이상의 숫자여야 합니다.';
  if (!(await exists(db, 'employee', 'employee_id', v.employeeId))) return '존재하지 않는 임직원입니다.';
  const params = { employeeId: v.employeeId, baseYear: v.baseYear, grantedDays: v.grantedDays };
  const found = await db.query(
    `SELECT annual_leave_id AS "annualLeaveId", is_confirmed AS "isConfirmed" FROM annual_leave
     WHERE employee_id = CAST(:employeeId AS bigint) AND base_year = CAST(:baseYear AS integer)`,
    params,
  );
  if (found.length > 0) {
    if (found[0].isConfirmed === true) return '확정된 연차입니다. 정해진 절차 없이 변경할 수 없습니다. (PERIOD_CLOSED_OR_APPROVED)';
    const id = found[0].annualLeaveId;
    await db.execute(
      `UPDATE annual_leave SET granted_days = CAST(:grantedDays AS numeric),
         remaining_days = CAST(:grantedDays AS numeric) - COALESCE(used_days, 0), updated_at = now()
       WHERE annual_leave_id = CAST(:id AS bigint)`,
      { grantedDays: v.grantedDays, id: String(id) },
    );
    await recordChange(db, userId, 'annual_leave', id, '연차 생성일수 수정');
    return null;
  }
  const rows = await db.query(
    `INSERT INTO annual_leave (employee_id, base_year, granted_days, is_confirmed, used_days, remaining_days, created_at, updated_at)
     VALUES (CAST(:employeeId AS bigint), CAST(:baseYear AS integer), CAST(:grantedDays AS numeric), false, 0, CAST(:grantedDays AS numeric), now(), now())
     RETURNING annual_leave_id AS "annualLeaveId"`,
    params,
  );
  await recordChange(db, userId, 'annual_leave', rows[0].annualLeaveId, '연차 등록');
  return null;
}

const SAVERS: Record<string, (db: Db, userId: string, v: Cells) => Promise<string | null>> = {
  PARTNER: savePartner,
  CARRYOVER: saveCarryover,
  ANNUAL_LEAVE: saveAnnualLeave,
};

@Controller('api/v1')
export class FnSfr00606Controller {
  @Post('/excel-uploads')
  @HttpCode(200)
  async uploadExcelData(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자', '인사 담당자', '근태 담당자', '급여 담당자', '자산 담당자');
    const data = checks.inputOf(req.body);
    const targetBusiness = data['targetBusiness'];
    const file = data['file'];
    if (typeof targetBusiness !== 'string' || !TARGETS.includes(targetBusiness)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '업로드 대상 업무를 선택해 주세요.');
    }
    if (typeof file !== 'string' || file.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '업로드할 파일을 선택해 주세요.');
    }
    const layout = LAYOUTS[targetBusiness];
    if (!layout) {
      throw new ApiError(422, 'INVALID_UPLOAD_FORMAT', '이 업무의 업로드 양식은 아직 제공하지 않습니다.');
    }
    const lines = file.split(/\r?\n/).filter((line) => line.trim() !== '');
    const header = lines.length > 0 ? lines[0].split('\t').map((c) => c.trim()) : [];
    if (header.length !== layout.length || header.some((c, i) => c !== layout[i])) {
      throw new ApiError(422, 'INVALID_UPLOAD_FORMAT', '양식의 머리글이 다릅니다. 내려받은 양식을 그대로 사용해 주세요.');
    }
    const bodyLines = lines.slice(1);
    if (bodyLines.length === 0) {
      throw new ApiError(422, 'INVALID_UPLOAD_FORMAT', '업로드할 행이 없습니다.');
    }
    const save = SAVERS[targetBusiness];
    return transaction(async (db: Db) => {
      const errors: string[] = [];
      let successCount = 0;
      for (let i = 0; i < bodyLines.length; i++) {
        const cells = bodyLines[i].split('\t').map((c) => c.trim());
        const rowNo = i + 2;
        if (cells.length !== layout.length) {
          errors.push(rowNo + '행: 칸 수가 양식과 다릅니다.');
          continue;
        }
        const values: Cells = {};
        layout.forEach((name, idx) => {
          values[name] = cells[idx];
        });
        const reason = await save(db, user.id, values);
        if (reason) {
          errors.push(rowNo + '행: ' + reason);
        } else {
          successCount += 1;
        }
      }
      const totalCount = bodyLines.length;
      const errorCount = totalCount - successCount;
      const errorDetail = errors.join('\n');
      const rows = await db.query(
        `INSERT INTO upload_history (uploader_id, target_business, file_name, uploaded_at, total_count, success_count, error_count, error_detail, process_mode, created_at, updated_at)
         VALUES (CAST(:userId AS bigint), :targetBusiness, :fileName, now(), :totalCount, :successCount, :errorCount, :errorDetail, :processMode, now(), now())
         RETURNING upload_history_id AS "uploadHistoryId"`,
        {
          userId: user.id,
          targetBusiness,
          fileName: targetBusiness + '.tsv',
          totalCount,
          successCount,
          errorCount,
          errorDetail: errorDetail === '' ? null : errorDetail,
          processMode: PROCESS_MODE,
        },
      );
      return {
        uploadHistoryId: rows[0].uploadHistoryId,
        totalCount,
        successCount,
        errorCount,
        errorDetail,
      };
    });
  }
}

