import { useState } from 'react';
import { Band, Badge, DataTable, Drawer, Field, Form, Num, Pairs, Select, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

const TARGETS: [string, string][] = [
  ['PARTNER', '거래처'],
  ['PERSONNEL_RECORD', '인사기록카드'],
  ['ANNUAL_LEAVE', '연차'],
  ['PAYROLL', '급여'],
  ['ASSET', '자산'],
  ['ATTENDANCE', '근태'],
  ['CARRYOVER', '계정별 초기이월'],
  ['COMMUTE_RECORD', '출퇴근 기록'],
  ['EDUCATION_ATTENDEE', '교육 참석자'],
  ['DAILY_WORKER_PAYMENT', '일용직 급여'],
];

function targetName(value: unknown): string {
  const found = TARGETS.find((t) => t[0] === value);
  return found ? found[1] : String(value ?? '');
}

export default function FnSfr00606Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [opening, setOpening] = useState(false);
  const [selected, setSelected] = useState<Row | null>(null);
  const [targetBusiness, setTargetBusiness] = useState('');
  const [fileText, setFileText] = useState('');
  const [fileName, setFileName] = useState('');

  function openUpload() {
    setTargetBusiness('');
    setFileText('');
    setFileName('');
    setOpening(true);
  }

  async function readFile(file: File | undefined) {
    if (!file) {
      setFileText('');
      setFileName('');
      return;
    }
    setFileName(file.name);
    setFileText(await file.text());
  }

  async function submit() {
    if (targetBusiness === '') {
      throw new Error('업로드 대상 업무를 선택해 주세요.');
    }
    if (fileText.trim() === '') {
      throw new Error('업로드할 파일을 선택해 주세요.');
    }
    const result = await call('POST', '/excel-uploads', role, { targetBusiness, file: fileText });
    setResults([{ ...result, targetBusiness }, ...results]);
    setOpening(false);
    notify('엑셀 업로드를 처리했습니다.');
  }

  return (
    <div className="doc">
      <h1>엑셀 일괄 업로드</h1>
      <Band total={results.length}>
        <button onClick={openUpload}>엑셀 업로드</button>
      </Band>
      <DataTable
        columns={[
          { key: 'uploadHistoryId', label: '업로드 이력 번호' },
          { key: 'targetBusiness', label: '업로드 대상 업무', render: (row) => targetName(row.targetBusiness) },
          { key: 'totalCount', label: '전체 건수', render: (row) => <Num value={row.totalCount} /> },
          { key: 'successCount', label: '정상 반영 건수', render: (row) => <Num value={row.successCount} /> },
          { key: 'errorCount', label: '오류 건수', render: (row) => <Num value={row.errorCount} /> },
        ]}
        rows={results}
        onRowClick={(row) => setSelected(row)}
        empty="아직 업로드한 내역이 없습니다. 엑셀 업로드 버튼을 눌러 시작하세요."
      />
      {opening && (
        <Drawer title="엑셀 업로드" onClose={() => setOpening(false)}>
          <Form
            onSubmit={submit}
            submit="업로드"
            note="오류가 있는 행은 반영하지 않고 정상 행만 반영합니다. 반영된 내용은 변경 이력에 남습니다."
          >
            <Field label="업로드 대상 업무" required>
              <Select value={targetBusiness} onChange={setTargetBusiness} options={TARGETS} />
            </Field>
            <Field label="양식에 맞춰 작성된 엑셀 파일" required wide hint={fileName === '' ? '탭으로 구분한 텍스트 파일을 선택해 주세요.' : fileName}>
              <input type="file" accept=".tsv,.txt,.csv" onChange={(e) => readFile(e.target.files?.[0])} />
            </Field>
          </Form>
        </Drawer>
      )}
      {selected && (
        <Drawer title="업로드 결과" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['업로드 이력 ID', String(selected.uploadHistoryId ?? '')],
              ['업로드 대상 업무', targetName(selected.targetBusiness)],
              ['전체 건수', <Num value={selected.totalCount} />],
              ['정상 반영 건수', <Num value={selected.successCount} />],
              ['오류 건수', <Num value={selected.errorCount} />],
              ['처리 결과', <Badge value={Number(selected.errorCount) === 0 ? '완료' : '반려'} />],
            ]}
          />
          <Field label="오류 내역" wide>
            <TextInput
              value={selected.errorDetail === '' || selected.errorDetail == null ? '오류 없이 모두 반영했습니다.' : selected.errorDetail}
              onChange={() => undefined}
              multiline
            />
          </Field>
        </Drawer>
      )}
    </div>
  );
}
